"use server"

import { redirect } from "next/navigation"

import { getServerEnv } from "@/lib/env/server"
import { safeMerchantNextPath } from "@/lib/navigation/safe-next-path"
import { createSupabaseServerClient } from "@/lib/supabase/server"

export type AuthActionState = {
  fields?: {
    name?: string
    email?: string
  }
  errors?: {
    name?: string
    email?: string
    password?: string
    form?: string
  }
  message?: string
}

function value(formData: FormData, key: string) {
  const raw = formData.get(key)
  return typeof raw === "string" ? raw.trim() : ""
}

function validateEmail(email: string) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)
}

export async function signUpAction(
  _state: AuthActionState,
  formData: FormData
): Promise<AuthActionState> {
  const name = value(formData, "name")
  const email = value(formData, "email").toLowerCase()
  const password = value(formData, "password")
  const errors: NonNullable<AuthActionState["errors"]> = {}

  if (name.length < 2) errors.name = "Enter your name."
  if (!validateEmail(email)) errors.email = "Enter a valid email address."
  if (password.length < 8) {
    errors.password = "Use at least 8 characters."
  }

  if (Object.keys(errors).length) {
    return { fields: { name, email }, errors }
  }

  const supabase = await createSupabaseServerClient()
  const env = getServerEnv()
  const { data, error } = await supabase.auth.signUp({
    email,
    password,
    options: {
      data: { name },
      emailRedirectTo: `${env.NEXT_PUBLIC_APP_URL}/auth/confirm?next=/app/onboarding`,
    },
  })

  if (error) {
    return {
      fields: { name, email },
      errors: { form: error.message },
    }
  }

  if (data.session) {
    redirect("/app/onboarding")
  }

  return {
    fields: { name, email },
    message: "Check your email to verify your account, then continue setup.",
  }
}

export async function signInAction(
  _state: AuthActionState,
  formData: FormData
): Promise<AuthActionState> {
  const email = value(formData, "email").toLowerCase()
  const password = value(formData, "password")
  const next = value(formData, "next") || "/app"
  const errors: NonNullable<AuthActionState["errors"]> = {}

  if (!validateEmail(email)) errors.email = "Enter a valid email address."
  if (!password) errors.password = "Enter your password."

  if (Object.keys(errors).length) {
    return { fields: { email }, errors }
  }

  const supabase = await createSupabaseServerClient()
  const { error } = await supabase.auth.signInWithPassword({ email, password })

  if (error) {
    return {
      fields: { email },
      errors: { form: "Email or password was not accepted." },
    }
  }

  redirect(safeMerchantNextPath(next))
}

export async function signOutAction() {
  const supabase = await createSupabaseServerClient()
  await supabase.auth.signOut()
  redirect("/login")
}

"use server"

import { redirect } from "next/navigation"

import { capturePostHogEvent } from "@/lib/analytics/events"
import { getCurrentMerchant } from "@/lib/auth/session"
import { createSupabaseServerClient } from "@/lib/supabase/server"

const CARD_SAVE_ERROR =
  "Mystery card could not be saved. Check your details and try again."
const REWARD_SAVE_ERROR =
  "Reward could not be saved. Check your details and try again."
const REWARD_UPDATE_ERROR = "Unable to update reward"

export type LoyaltyCardActionState = {
  fields?: {
    cardId?: string
    cardName?: string
    stampsRequired?: string
    rewardTerms?: string
    minSpendPence?: string
    isActive?: boolean
  }
  errors?: {
    cardName?: string
    stampsRequired?: string
    rewardTerms?: string
    minSpendPence?: string
    form?: string
  }
}

export type RewardPoolItemActionState = {
  fields?: {
    rewardPoolItemId?: string
    loyaltyCardId?: string
    rewardName?: string
    rewardTerms?: string
    minSpendPence?: string
    weight?: string
    displayOrder?: string
    isActive?: boolean
  }
  errors?: {
    loyaltyCardId?: string
    rewardName?: string
    rewardTerms?: string
    minSpendPence?: string
    weight?: string
    displayOrder?: string
    form?: string
  }
}

function value(formData: FormData, key: string) {
  const raw = formData.get(key)
  return typeof raw === "string" ? raw.trim() : ""
}

function parseInteger(input: string) {
  if (!/^\d+$/.test(input)) return null
  return Number.parseInt(input, 10)
}

function rewardPoolFields(formData: FormData) {
  return {
    rewardPoolItemId: value(formData, "rewardPoolItemId"),
    loyaltyCardId: value(formData, "loyaltyCardId"),
    rewardName: value(formData, "rewardName"),
    rewardTerms: value(formData, "rewardTerms"),
    minSpendPence: value(formData, "minSpendPence"),
    weight: value(formData, "weight") || "1",
    displayOrder: value(formData, "displayOrder") || "0",
    isActive: formData.get("isActive") === "on",
  }
}

export async function saveLoyaltyCardAction(
  _state: LoyaltyCardActionState,
  formData: FormData
): Promise<LoyaltyCardActionState> {
  const merchant = await getCurrentMerchant()

  if (!merchant) {
    return { errors: { form: "Complete merchant onboarding before saving a card." } }
  }

  const cardId = value(formData, "cardId")
  const cardName = value(formData, "cardName")
  const stampsRequired = value(formData, "stampsRequired")
  const rewardTerms = value(formData, "rewardTerms")
  const minSpendPence = value(formData, "minSpendPence")
  const isActive = formData.get("isActive") === "on"
  const fields = {
    cardId,
    cardName,
    stampsRequired,
    rewardTerms,
    minSpendPence,
    isActive,
  }
  const errors: NonNullable<LoyaltyCardActionState["errors"]> = {}
  const parsedStampsRequired = parseInteger(stampsRequired)
  const parsedMinSpendPence = minSpendPence ? parseInteger(minSpendPence) : null

  if (!cardName) errors.cardName = "Enter a card name."
  if (cardName.length > 80) errors.cardName = "Use 80 characters or fewer."

  if (parsedStampsRequired === null) {
    errors.stampsRequired = "Enter a whole number of stamps."
  } else if (parsedStampsRequired < 1) {
    errors.stampsRequired = "Use at least 1 stamp."
  } else if (parsedStampsRequired > 99) {
    errors.stampsRequired = "Use 99 stamps or fewer."
  }

  if (!rewardTerms) {
    errors.rewardTerms = "Enter clear mystery reward terms."
  } else if (rewardTerms.length < 12) {
    errors.rewardTerms = "Add enough detail for customers to understand the offer."
  } else if (rewardTerms.length > 500) {
    errors.rewardTerms = "Use 500 characters or fewer."
  }

  if (minSpendPence && parsedMinSpendPence === null) {
    errors.minSpendPence = "Enter minimum spend in whole pence."
  } else if (parsedMinSpendPence !== null && parsedMinSpendPence > 100000) {
    errors.minSpendPence = "Use a minimum spend of GBP 1,000 or less."
  }

  if (Object.keys(errors).length || parsedStampsRequired === null) {
    return { fields, errors }
  }

  const supabase = await createSupabaseServerClient()
  const { error } = await supabase.rpc("save_loyalty_card", {
    p_merchant_id: merchant.id,
    p_card_id: cardId || null,
    p_card_name: cardName,
    p_stamps_required: parsedStampsRequired,
    p_reward_name: "Surprise reward",
    p_reward_terms: rewardTerms,
    p_min_spend_pence: parsedMinSpendPence,
    p_is_active: isActive,
  })

  if (error) {
    return {
      fields,
      errors: {
        form: CARD_SAVE_ERROR,
      },
    }
  }

  await capturePostHogEvent({
    eventName: cardId ? "loyalty_card_updated" : "loyalty_card_created",
    merchantId: merchant.id,
    actorType: "merchant",
    actorId: merchant.id,
  })

  redirect("/app/launch?tab=card&saved=1")
}

export async function saveRewardPoolItemAction(
  _state: RewardPoolItemActionState,
  formData: FormData
): Promise<RewardPoolItemActionState> {
  const merchant = await getCurrentMerchant()

  if (!merchant) {
    return {
      errors: { form: "Complete merchant onboarding before saving rewards." },
    }
  }

  const fields = rewardPoolFields(formData)
  const errors: NonNullable<RewardPoolItemActionState["errors"]> = {}
  const parsedMinSpendPence = fields.minSpendPence
    ? parseInteger(fields.minSpendPence)
    : null
  const parsedWeight = parseInteger(fields.weight)
  const parsedDisplayOrder = parseInteger(fields.displayOrder)

  if (!fields.loyaltyCardId) {
    errors.loyaltyCardId = "Save the mystery card before adding rewards."
  }

  if (!fields.rewardName) errors.rewardName = "Enter the reward name."
  if (fields.rewardName.length > 100) {
    errors.rewardName = "Use 100 characters or fewer."
  }

  if (!fields.rewardTerms) {
    errors.rewardTerms = "Enter clear customer-facing reward terms."
  } else if (fields.rewardTerms.length < 12) {
    errors.rewardTerms = "Add enough detail for customers to understand the offer."
  } else if (fields.rewardTerms.length > 500) {
    errors.rewardTerms = "Use 500 characters or fewer."
  }

  if (fields.minSpendPence && parsedMinSpendPence === null) {
    errors.minSpendPence = "Enter minimum spend in whole pence."
  } else if (parsedMinSpendPence !== null && parsedMinSpendPence > 100000) {
    errors.minSpendPence = "Use a minimum spend of GBP 1,000 or less."
  }

  if (parsedWeight === null) {
    errors.weight = "Enter a whole-number weight."
  } else if (parsedWeight < 1) {
    errors.weight = "Use a weight of at least 1."
  } else if (parsedWeight > 1000) {
    errors.weight = "Use a weight of 1,000 or less."
  }

  if (parsedDisplayOrder === null) {
    errors.displayOrder = "Enter a whole-number display order."
  }

  if (
    Object.keys(errors).length ||
    parsedWeight === null ||
    parsedDisplayOrder === null
  ) {
    return { fields, errors }
  }

  const supabase = await createSupabaseServerClient()
  const { data, error } = await supabase.rpc("upsert_reward_pool_item", {
    p_merchant_id: merchant.id,
    p_loyalty_card_id: fields.loyaltyCardId,
    p_reward_pool_item_id: fields.rewardPoolItemId || null,
    p_reward_name: fields.rewardName,
    p_reward_terms: fields.rewardTerms,
    p_min_spend_pence: parsedMinSpendPence,
    p_weight: parsedWeight,
    p_is_active: fields.isActive,
    p_display_order: parsedDisplayOrder,
  })

  if (error) {
    return {
      fields,
      errors: {
        form: REWARD_SAVE_ERROR,
      },
    }
  }

  await capturePostHogEvent({
    eventName: data?.[0]?.saved_action ?? "reward_pool_item_saved",
    merchantId: merchant.id,
    actorType: "merchant",
    actorId: merchant.id,
    metadata: { loyalty_card_id: fields.loyaltyCardId },
  })

  redirect("/app/launch?tab=card&saved=pool")
}

export async function deleteRewardPoolItemAction(formData: FormData) {
  const merchant = await getCurrentMerchant()
  const rewardPoolItemId = value(formData, "rewardPoolItemId")

  if (!merchant || !rewardPoolItemId) {
    redirect(
      `/app/launch?tab=card&error=${encodeURIComponent(REWARD_UPDATE_ERROR)}`
    )
  }

  const supabase = await createSupabaseServerClient()
  const { data, error } = await supabase.rpc("delete_reward_pool_item", {
    p_merchant_id: merchant.id,
    p_reward_pool_item_id: rewardPoolItemId,
  })

  if (error) {
    redirect(
      `/app/launch?tab=card&error=${encodeURIComponent(REWARD_UPDATE_ERROR)}`
    )
  }

  await capturePostHogEvent({
    eventName: data?.[0]?.deleted
      ? "reward_pool_item_deleted"
      : "reward_pool_item_archived",
    merchantId: merchant.id,
    actorType: "merchant",
    actorId: merchant.id,
    metadata: { reward_pool_item_id: rewardPoolItemId },
  })

  redirect("/app/launch?tab=card&saved=pool")
}

"use server"

import { revalidatePath } from "next/cache"

import { getCurrentMerchant } from "@/lib/auth/session"
import { resolveStructuredVenueAddress } from "@/lib/merchant/resolve-venue-address"
import {
  buildProviderVenueAddress,
  parseManualGeofencePin,
  parseVenueAddressFields,
  validateVenueAddressFields,
  type VenueAddressPayload,
  type VenueAddressFieldErrors,
  type VenueAddressFormFields,
} from "@/lib/merchant/venue-address"
import { createSupabaseServerClient } from "@/lib/supabase/server"

export type VenueLocationActionState = {
  fields?: VenueAddressFormFields & {
    venueName?: string
    geofenceRadiusMeters?: string
    requireGeofence?: boolean
    /** Submitted manual pin coordinates, echoed back for re-render. */
    venueLatitude?: string
    venueLongitude?: string
    geofencePinSource?: string
  }
  errors?: VenueAddressFieldErrors & {
    venueName?: string
    geofenceRadiusMeters?: string
    form?: string
  }
  saved?: boolean
}

type VenueLocationWritePayload = Omit<
  VenueAddressPayload,
  "address_provider" | "address_provider_id"
> & {
  merchant_id: string
  name: string
  address_provider: VenueAddressPayload["address_provider"]
  address_provider_id: VenueAddressPayload["address_provider_id"]
  latitude: number
  longitude: number
  geofence_radius_meters: number
  require_geofence: boolean
  geocoded_at: string
  geofence_pin_source: "geocoded" | "merchant_pin"
  geofence_pin_updated_at: string
  is_primary: boolean
}

export async function saveVenueLocationAction(
  _state: VenueLocationActionState,
  formData: FormData
): Promise<VenueLocationActionState> {
  const merchant = await getCurrentMerchant()

  if (!merchant) {
    return { errors: { form: "Complete merchant onboarding first." } }
  }

  const venueName = value(formData, "venueName") || "Main venue"
  const addressFields = parseVenueAddressFields(formData)
  const geofenceRadiusMeters = value(formData, "geofenceRadiusMeters") || "150"
  const requireGeofence = formData.get("requireGeofence") === "on"
  const geofencePinSource = value(formData, "geofencePinSource")
  const venueLatitude = value(formData, "venueLatitude")
  const venueLongitude = value(formData, "venueLongitude")
  const manualPin =
    geofencePinSource === "merchant_pin"
      ? parseManualGeofencePin(venueLatitude, venueLongitude)
      : null
  const fields = {
    venueName,
    ...addressFields,
    geofenceRadiusMeters,
    requireGeofence,
    venueLatitude,
    venueLongitude,
    geofencePinSource,
  }
  const errors: NonNullable<VenueLocationActionState["errors"]> = {
    ...validateVenueAddressFields(addressFields),
  }
  const radius = parseInteger(geofenceRadiusMeters)

  if (!venueName) errors.venueName = "Enter the venue name."
  if (venueName.length > 120) errors.venueName = "Use 120 characters or fewer."
  if (radius === null) {
    errors.geofenceRadiusMeters = "Enter a whole-number radius."
  } else if (radius < 25) {
    errors.geofenceRadiusMeters = "Use at least 25 metres."
  } else if (radius > 1000) {
    errors.geofenceRadiusMeters = "Use 1,000 metres or fewer."
  }

  // A submitted manual pin must carry finite, in-range coordinates; reject an
  // invalid pin rather than silently falling back to the geocode.
  if (geofencePinSource === "merchant_pin" && manualPin === null) {
    errors.form = "Drop the pin on the map before saving."
  }

  if (Object.keys(errors).length > 0 || radius === null) {
    return { fields, errors }
  }

  // A Google Places selection arrives with a provider id and validated,
  // GB-bounded coordinates, so it skips the Nominatim geocode and records its
  // provenance through the existing provider columns. Manual entry still
  // geocodes the structured postcode through resolveStructuredVenueAddress.
  const isProviderLookup =
    value(formData, "addressSource") === "provider_lookup" &&
    value(formData, "addressProvider") === "google_places"
  const resolved = isProviderLookup
    ? buildProviderVenueAddress({
        fields: addressFields,
        providerId: value(formData, "addressProviderId"),
        latitude: value(formData, "providerLatitude"),
        longitude: value(formData, "providerLongitude"),
      })
    : await resolveStructuredVenueAddress(addressFields)

  if ("errors" in resolved) {
    return { fields, errors: { ...errors, ...resolved.errors } }
  }

  if ("error" in resolved) {
    return { fields, errors: { ...errors, address: resolved.error } }
  }

  // A valid manual pin wins over the resolved coordinates (postcode-centroid
  // geocode or provider location); provenance is recorded in geofence_pin_source,
  // never by overloading the address source.
  const savedAt = new Date().toISOString()
  const payload: VenueLocationWritePayload = {
    merchant_id: merchant.id,
    name: venueName,
    ...resolved.payload,
    latitude: manualPin?.latitude ?? resolved.payload.latitude,
    longitude: manualPin?.longitude ?? resolved.payload.longitude,
    geofence_radius_meters: radius,
    require_geofence: requireGeofence,
    geocoded_at: savedAt,
    geofence_pin_source: manualPin ? "merchant_pin" : "geocoded",
    geofence_pin_updated_at: savedAt,
    is_primary: true,
  }

  const supabase = await createSupabaseServerClient()
  const { data: existingLocation, error: loadError } = await supabase
    .from("merchant_locations")
    .select("id")
    .eq("merchant_id", merchant.id)
    .order("is_primary", { ascending: false })
    .order("created_at", { ascending: true })
    .limit(1)
    .maybeSingle()

  if (loadError) {
    return { fields, errors: { form: "Unable to load venue location." } }
  }

  const write = existingLocation
    ? supabase
        .from("merchant_locations")
        .update(payload)
        .eq("id", existingLocation.id)
    : supabase.from("merchant_locations").insert(payload)
  const { error: writeError } = await write

  if (writeError) {
    return { fields, errors: { form: "Unable to save venue location." } }
  }

  revalidatePath("/app/launch")
  revalidatePath("/app")

  return { fields, saved: true }
}

function value(formData: FormData, key: string) {
  const raw = formData.get(key)
  return typeof raw === "string" ? raw.trim() : ""
}

function parseInteger(input: string) {
  if (!/^\d+$/.test(input)) return null
  return Number.parseInt(input, 10)
}

import Link from "next/link"
import { redirect } from "next/navigation"
import { Suspense } from "react"

import { PageTitle } from "@/components/brand"
import { LaunchReadinessPanel } from "@/components/merchant/launch-readiness-panel"
import { LaunchPanelSkeleton } from "@/components/merchant/loading-skeletons"
import { CardPanel } from "@/components/merchant/launch/card-panel"
import { QrPanel } from "@/components/merchant/launch/qr-panel"
import { VenuePanel } from "@/components/merchant/launch/venue-panel"
import { Button } from "@/components/ui/button"
import { getCurrentMerchant } from "@/lib/auth/session"
import { buildLaunchReadiness } from "@/lib/merchant/launch-readiness"
import { getQrSetup } from "@/lib/merchant/qr-code"

export const dynamic = "force-dynamic"

const TABS = [
  { id: "card", label: "Your card and reward" },
  { id: "venue", label: "Your venue" },
  { id: "qr", label: "Print your QR" },
] as const

type TabId = (typeof TABS)[number]["id"]

type LaunchPageProps = {
  searchParams: Promise<{
    tab?: string
    saved?: string
    error?: string
    created?: string
    enabled?: string
    disabled?: string
  }>
}

type LaunchSearchParams = Awaited<LaunchPageProps["searchParams"]>

export default async function LaunchPage({ searchParams }: LaunchPageProps) {
  const params = await searchParams
  const merchant = await getCurrentMerchant()

  if (!merchant) {
    redirect("/app/onboarding")
  }

  const { activeCard, activeRewardPoolItemCount, qrCode, location } =
    await getQrSetup()

  const launchReadiness = buildLaunchReadiness({
    activeCard,
    activeRewardPoolItemCount,
    qrCode,
    location,
  })

  // Live merchants land on their launch kit; everyone else opens the next
  // unfinished step. An explicit `?tab=` always wins so deep links stay stable.
  const defaultTab: TabId = launchReadiness.launchReady
    ? "qr"
    : (launchReadiness.nextStep?.tab ?? "card")
  const requested = params.tab
  const activeTab: TabId = isTabId(requested) ? requested : defaultTab

  return (
    <div className="grid gap-6">
      <PageTitle
        eyebrow="Merchant setup"
        title={
          launchReadiness.launchReady
            ? "You're live"
            : "Bring your venue to life"
        }
        description={
          launchReadiness.launchReady
            ? "Customers can scan, join, and collect. Your launch kit is below, with the bits you can still adjust."
            : "Four stamps and you're live. We always point you at the one thing left to do."
        }
        actions={
          launchReadiness.launchReady ? (
            <Button asChild variant="secondary">
              <Link href="/app/launch?tab=qr">Open launch kit</Link>
            </Button>
          ) : undefined
        }
      />

      <LaunchReadinessPanel
        readiness={launchReadiness}
        showHeader={false}
        activeTab={activeTab}
      />

      {/* Keyed by tab so each tab switch re-suspends and streams only the panel
          body — the title and readiness spine above stay put. */}
      <Suspense
        key={activeTab}
        fallback={<LaunchPanelSkeleton tab={activeTab} />}
      >
        <LaunchActivePanel activeTab={activeTab} params={params} />
      </Suspense>
    </div>
  )
}

function LaunchActivePanel({
  activeTab,
  params,
}: {
  activeTab: TabId
  params: LaunchSearchParams
}) {
  return (
    <div className="grid gap-5">
      {activeTab === "card" ? (
        <CardPanel params={params} />
      ) : activeTab === "venue" ? (
        <VenuePanel />
      ) : (
        <QrPanel params={params} />
      )}
    </div>
  )
}

function isTabId(value: string | undefined): value is TabId {
  return TABS.some((tab) => tab.id === value)
}

import { headers } from "next/headers"
import { redirect } from "next/navigation"

import { signOutAction } from "@/app/(auth)/actions"
import { MerchantAppShell } from "@/components/layout"
import { getCurrentUser } from "@/lib/auth/session"
import { merchantLoginHref } from "@/lib/navigation/safe-next-path"
import { readMerchantRequestPath } from "@/lib/navigation/request-path"

export default async function MerchantAppLayout({
  children,
}: {
  children: React.ReactNode
}) {
  const user = await getCurrentUser()

  if (!user) {
    const returnPath = readMerchantRequestPath(await headers())
    redirect(merchantLoginHref(returnPath))
  }

  return (
    <MerchantAppShell signOutAction={signOutAction}>
      {children}
    </MerchantAppShell>
  )
}

"use server"

import { redirect } from "next/navigation"

import { capturePostHogEvent } from "@/lib/analytics/events"
import { getQrSetup } from "@/lib/merchant/qr-code"
import { createSupabaseServerClient } from "@/lib/supabase/server"

const QR_REWARD_POOL_ERROR =
  "Add at least 3 active mystery rewards before launching the QR."
const QR_CREATE_ERROR = "Unable to create QR"
const QR_UPDATE_ERROR = "Unable to update QR"

export async function generateQrCodeAction() {
  const { merchant, activeCard, activeRewardPoolItemCount } = await getQrSetup()

  if (!merchant) {
    redirect("/app/onboarding")
  }

  if (!activeCard) {
    redirect("/app/launch?tab=card")
  }

  if (activeRewardPoolItemCount < 3) {
    redirect(
      `/app/launch?tab=qr&error=${encodeURIComponent(QR_REWARD_POOL_ERROR)}`
    )
  }

  const supabase = await createSupabaseServerClient()
  const { error } = await supabase.rpc("create_or_get_join_qr", {
    p_merchant_id: merchant.id,
    p_loyalty_card_id: activeCard.id,
  })

  if (error) {
    redirect(`/app/launch?tab=qr&error=${encodeURIComponent(QR_CREATE_ERROR)}`)
  }

  await capturePostHogEvent({
    eventName: "qr_created",
    merchantId: merchant.id,
    actorType: "merchant",
    actorId: merchant.id,
    metadata: { source: "merchant_qr_action" },
  })

  redirect("/app/launch?tab=qr&created=1")
}

export async function setQrActiveAction(formData: FormData) {
  const { merchant } = await getQrSetup()
  const qrCodeId = formData.get("qrCodeId")
  const nextActive = formData.get("nextActive") === "true"

  if (!merchant || typeof qrCodeId !== "string") {
    redirect(`/app/launch?tab=qr&error=${encodeURIComponent(QR_UPDATE_ERROR)}`)
  }

  const supabase = await createSupabaseServerClient()
  const { error } = await supabase.rpc("set_qr_active", {
    p_merchant_id: merchant.id,
    p_qr_code_id: qrCodeId,
    p_is_active: nextActive,
  })

  if (error) {
    redirect(`/app/launch?tab=qr&error=${encodeURIComponent(QR_UPDATE_ERROR)}`)
  }

  await capturePostHogEvent({
    eventName: nextActive ? "qr_enabled" : "qr_disabled",
    merchantId: merchant.id,
    qrCodeId,
    actorType: "merchant",
    actorId: merchant.id,
    metadata: {
      source: "merchant_qr_action",
      is_active: nextActive,
    },
  })

  redirect(`/app/launch?tab=qr&${nextActive ? "enabled" : "disabled"}=1`)
}

import type { ComponentProps } from "react"
import { HugeiconsIcon } from "@hugeicons/react"

