import { VenueLocationForm } from "@/components/merchant/launch/venue-location-form"
import { getCurrentVenueLocation } from "@/lib/merchant/location"
import { venueAddressFieldsFromLocation } from "@/lib/merchant/venue-address"

export async function VenuePanel() {
  const { merchant, location } = await getCurrentVenueLocation()

  if (!merchant) {
    redirect("/app/onboarding")
  }

  return (
    <div className="grid gap-4">
      <VenueLocationForm
        initialValues={{
          venueName: location?.name ?? "Main venue",
          ...venueAddressFieldsFromLocation({
            address: location?.address ?? null,
            address_line_1: location?.address_line_1,
            address_line_2: location?.address_line_2,
            address_city: location?.address_city,
            address_postcode: location?.address_postcode,
          }),
          geofenceRadiusMeters: String(location?.geofence_radius_meters ?? 150),
          requireGeofence: location?.require_geofence ?? false,
        }}
        geocoded={
          location?.latitude != null && location?.longitude != null
            ? { latitude: location.latitude, longitude: location.longitude }
            : null
        }
        pinSource={
          location?.geofence_pin_source === "merchant_pin"
            ? "merchant_pin"
            : "geocoded"
        }
      />
    </div>
  )
}

"use client"

import { useEffect, useRef } from "react"

import * as L from "leaflet"
import "leaflet/dist/leaflet.css"

export type VenuePinMapProps = {
  latitude: number
  longitude: number
  radiusMeters: number
  /** Fires after a drag settles with the new marker coordinates. */
  onPinChange: (coordinates: { latitude: number; longitude: number }) => void
}

const PIN_COLOR = "#b8742c"

// Self-contained HTML marker so Leaflet's default image assets (which break
// under bundlers) are never requested.
const MARKER_HTML =
  '<span style="display:block;width:22px;height:22px;border-radius:9999px;' +
  `background:${PIN_COLOR};border:3px solid #ffffff;` +
  'box-shadow:0 1px 5px rgba(0,0,0,0.45);"></span>'

/**
 * Client-only draggable geofence pin. Direct Leaflet (no React wrapper): the map is
 * built in an effect, kept in refs, and torn down on unmount. A second effect
 * keeps the marker, circle, and radius in sync with controlled props without
 * rebuilding the map.
 */
export default function VenuePinMap({
  latitude,
  longitude,
  radiusMeters,
  onPinChange,
}: VenuePinMapProps) {
  const containerRef = useRef<HTMLDivElement | null>(null)
  const mapRef = useRef<L.Map | null>(null)
  const markerRef = useRef<L.Marker | null>(null)
  const circleRef = useRef<L.Circle | null>(null)
  const initialRef = useRef({ latitude, longitude, radiusMeters })
  const onPinChangeRef = useRef(onPinChange)

  useEffect(() => {
    onPinChangeRef.current = onPinChange
  }, [onPinChange])

  useEffect(() => {
    const container = containerRef.current
    if (!container || mapRef.current) return

    const {
      latitude: lat0,
      longitude: lng0,
      radiusMeters: radius0,
    } = initialRef.current

    const map = L.map(container, {
      center: [lat0, lng0],
      zoom: 17,
      scrollWheelZoom: false,
    })
    mapRef.current = map

    L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
      attribution:
        '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors',
      maxZoom: 19,
    }).addTo(map)

    const circle = L.circle([lat0, lng0], {
      radius: radius0,
      color: PIN_COLOR,
      weight: 2,
      fillColor: PIN_COLOR,
      fillOpacity: 0.12,
    }).addTo(map)
    circleRef.current = circle

    const marker = L.marker([lat0, lng0], {
      draggable: true,
      keyboard: false,
      icon: L.divIcon({
        className: "venue-pin-marker",
        html: MARKER_HTML,
        iconSize: [22, 22],
        iconAnchor: [11, 11],
      }),
    }).addTo(map)
    markerRef.current = marker

    marker.on("drag", () => {
      const { lat, lng } = marker.getLatLng()
      circle.setLatLng([lat, lng])
    })
    marker.on("dragend", () => {
      const { lat, lng } = marker.getLatLng()
      onPinChangeRef.current({ latitude: lat, longitude: lng })
    })

    // Leaflet sizes itself from the container, which may still be settling on
    // mount; recompute now and on any later resize.
    const invalidate = () => map.invalidateSize()
    const frame = requestAnimationFrame(invalidate)
    const observer = new ResizeObserver(invalidate)
    observer.observe(container)

    return () => {
      cancelAnimationFrame(frame)
      observer.disconnect()
      map.remove()
      mapRef.current = null
      markerRef.current = null
      circleRef.current = null
    }
  }, [])

  useEffect(() => {
    const marker = markerRef.current
    const circle = circleRef.current
    if (!marker || !circle) return
    marker.setLatLng([latitude, longitude])
    circle.setLatLng([latitude, longitude])
    circle.setRadius(radiusMeters)
  }, [latitude, longitude, radiusMeters])

  return (
    <div
      ref={containerRef}
      data-testid="venue-pin-map"
      role="application"
      aria-label="Drag the pin to your venue entrance for the soft GPS check"
      className="h-64 w-full overflow-hidden rounded-lg border-2 border-ink"
    />
  )
}

"use client"

import { useEffect, useRef, useState } from "react"

import {
  mapGoogleAddressComponents,
  type GoogleAddressComponent,
  type VenueAddressFormFields,
} from "@/lib/merchant/venue-address"

/** A validated-on-the-client Google Places selection handed to the venue form. */
export type VenuePlaceSelection = {
  placeId: string
  displayName: string
  fields: VenueAddressFormFields
  latitude: number
  longitude: number
}

// Only the fields the venue form needs, per Places API (New) billing guidance.
const REQUIRED_PLACE_FIELDS = [
  "id",
  "displayName",
  "formattedAddress",
  "addressComponents",
  "location",
] as const

// idle states the merchant can see; the form keeps manual entry usable in all of
// them, so a missing key or a load failure never blocks venue setup.
type WidgetStatus = "unconfigured" | "loading" | "ready" | "error"

type GooglePlaceLocation =
  | { lat: () => number; lng: () => number }
  | { lat: number; lng: number }

type GooglePlaceComponent = {
  longText?: string | null
  shortText?: string | null
  types?: string[]
}

type GooglePlace = {
  id?: string
  displayName?: string | { text?: string } | null
  formattedAddress?: string | null
  addressComponents?: GooglePlaceComponent[] | null
  location?: GooglePlaceLocation | null
  fetchFields: (options: { fields: string[] }) => Promise<unknown>
}

type GmpSelectEvent = Event & {
  placePrediction?: { toPlace: () => GooglePlace } | null
  place?: GooglePlace | null
}

type PlaceAutocompleteElementConstructor = new (options: {
  includedRegionCodes?: string[]
  includedPrimaryTypes?: string[]
}) => HTMLElement

type PlacesLibrary = {
  PlaceAutocompleteElement: PlaceAutocompleteElementConstructor
}

type GoogleMaps = {
  importLibrary: (name: string) => Promise<unknown>
}

declare global {
  interface Window {
    google?: { maps?: GoogleMaps }
  }
}

const MAPS_CALLBACK = "__nabaperksGoogleMapsReady"
let mapsLoaderPromise: Promise<GoogleMaps> | null = null

/**
 * Inline dynamic loader for the Maps JavaScript API `places` library. Loads the
 * script only when a public key exists, reuses a single in-flight promise, and
 * resolves immediately when `importLibrary` is already present (which is how the
 * preview/Playwright mock injects a fake Google without any network call).
 */
function loadGoogleMaps(apiKey: string): Promise<GoogleMaps> {
  if (typeof window === "undefined") {
    return Promise.reject(
      new Error("Google Maps can only load in the browser.")
    )
  }

  const existing = window.google?.maps
  if (existing?.importLibrary) return Promise.resolve(existing)
  if (mapsLoaderPromise) return mapsLoaderPromise

  mapsLoaderPromise = new Promise<GoogleMaps>((resolve, reject) => {
    const settle = () => {
      const maps = window.google?.maps
      if (maps?.importLibrary) resolve(maps)
      else reject(new Error("Google Maps loaded without importLibrary."))
    }

    ;(window as unknown as Record<string, unknown>)[MAPS_CALLBACK] = settle

    const params = new URLSearchParams({
      key: apiKey,
      v: "weekly",
      libraries: "places",
      loading: "async",
      callback: MAPS_CALLBACK,
    })
    const script = document.createElement("script")
    script.src = `https://maps.googleapis.com/maps/api/js?${params.toString()}`
    script.async = true
    script.onerror = () => {
      mapsLoaderPromise = null
      reject(new Error("Google Maps script failed to load."))
    }
    document.head.append(script)
  })

  return mapsLoaderPromise
}

function readLocation(
  location: GooglePlaceLocation | null | undefined
): { latitude: number; longitude: number } | null {
  if (!location) return null
  const rawLat = location.lat
  const rawLng = location.lng
  const latitude = typeof rawLat === "function" ? rawLat() : rawLat
  const longitude = typeof rawLng === "function" ? rawLng() : rawLng
  if (typeof latitude !== "number" || typeof longitude !== "number") return null
  if (!Number.isFinite(latitude) || !Number.isFinite(longitude)) return null
  return { latitude, longitude }
}

function readDisplayName(displayName: GooglePlace["displayName"]): string {
  if (typeof displayName === "string") return displayName
  if (displayName && typeof displayName.text === "string")
    return displayName.text
  return ""
}

function toAddressComponents(
  components: GooglePlaceComponent[] | null | undefined
): GoogleAddressComponent[] {
  if (!Array.isArray(components)) return []
  return components.map((component) => ({
    longText: component.longText ?? null,
    shortText: component.shortText ?? null,
    types: Array.isArray(component.types) ? component.types : [],
  }))
}

function toVenuePlaceSelection(place: GooglePlace): VenuePlaceSelection | null {
  const coordinates = readLocation(place.location)
  if (!coordinates) return null
  const placeId = typeof place.id === "string" ? place.id.trim() : ""
  if (!placeId) return null

  return {
    placeId,
    displayName: readDisplayName(place.displayName),
    fields: mapGoogleAddressComponents(
      toAddressComponents(place.addressComponents)
    ),
    latitude: coordinates.latitude,
    longitude: coordinates.longitude,
  }
}

/**
 * Client-only Google Places (New) venue search for the merchant Launch venue
 * step. When `NEXT_PUBLIC_GOOGLE_MAPS_API_KEY` is absent the component renders
 * nothing and the manual address fields below it stay fully usable. A load or
 * selection failure is caught and surfaced as a quiet hint, never thrown.
 */
export function VenuePlaceAutocomplete({
  onPlaceSelected,
  apiKey: apiKeyOverride,
}: {
  onPlaceSelected: (selection: VenuePlaceSelection) => void
  /** Optional key injection for the dev preview harness. Production callers omit
   *  it so the public env var is the single source of truth. */
  apiKey?: string
}) {
  const apiKey = apiKeyOverride ?? process.env.NEXT_PUBLIC_GOOGLE_MAPS_API_KEY
  const containerRef = useRef<HTMLDivElement | null>(null)
  const onSelectedRef = useRef(onPlaceSelected)
  const [status, setStatus] = useState<WidgetStatus>(
    apiKey ? "loading" : "unconfigured"
  )

  useEffect(() => {
    onSelectedRef.current = onPlaceSelected
  }, [onPlaceSelected])

  useEffect(() => {
    if (!apiKey) return
    let cancelled = false
    let detach = () => {}

    const handleSelect = (event: Event) => {
      const selectEvent = event as GmpSelectEvent
      void resolveSelection(selectEvent)
    }

    async function resolveSelection(selectEvent: GmpSelectEvent) {
      try {
        const place =
          selectEvent.placePrediction?.toPlace() ?? selectEvent.place ?? null
        if (!place) return
        await place.fetchFields({ fields: [...REQUIRED_PLACE_FIELDS] })
        const selection = toVenuePlaceSelection(place)
        if (selection) onSelectedRef.current(selection)
      } catch {
        // A failed selection must not break the form; manual entry remains.
      }
    }

    async function mount(key: string) {
      try {
        const maps = await loadGoogleMaps(key)
        const library = (await maps.importLibrary("places")) as PlacesLibrary
        const container = containerRef.current
        if (cancelled || !container) return

        const element = new library.PlaceAutocompleteElement({
          includedRegionCodes: ["gb"],
          includedPrimaryTypes: ["establishment"],
        })
        element.classList.add("w-full")
        element.setAttribute("placeholder", "Search for your venue")
        container.replaceChildren(element)
        element.addEventListener("gmp-select", handleSelect)
        detach = () => element.removeEventListener("gmp-select", handleSelect)
        setStatus("ready")
      } catch {
        if (!cancelled) setStatus("error")
      }
    }

    void mount(apiKey)

    return () => {
      cancelled = true
      detach()
    }
  }, [apiKey])

  // Unconfigured: render nothing so the manual address fields below stand alone.
  if (!apiKey) return null

  return (
    <div className="grid gap-2">
      <span className="text-sm font-bold">Find your venue</span>
      <div
        ref={containerRef}
        data-testid="venue-place-autocomplete"
        data-status={status}
        className="min-h-11"
      />
      {status === "loading" ? (
        <p className="text-xs leading-5 text-muted-foreground">
          Loading venue search…
        </p>
      ) : null}
      {status === "ready" ? (
        <p className="text-xs leading-5 text-muted-foreground">
          Search Google for your venue, or enter the address below.
        </p>
      ) : null}
      {status === "error" ? (
        <p className="text-xs leading-5 text-muted-foreground">
          Venue search is unavailable right now. Enter your address below.
        </p>
      ) : null}
    </div>
  )
}

"use client"

import { useActionState, useState } from "react"
import { GiftIcon } from "@hugeicons/core-free-icons"

import {
  deleteRewardPoolItemAction,
  saveLoyaltyCardAction,
  saveRewardPoolItemAction,
  type LoyaltyCardActionState,
  type RewardPoolItemActionState,
} from "@/app/app/card/actions"
import {
  EmptyState,
  Eyebrow,
  MonoTag,
  PageTitle,
  SectionHeader,
  VenueMark,
} from "@/components/brand"
import { Disclosure } from "@/components/merchant/launch/disclosure"
import { StatusBanner } from "@/components/loyalty/status-banner"
import { Button } from "@/components/ui/button"

type LoyaltyCardFormValues = {
  cardId?: string
  cardName: string
  stampsRequired: string
  rewardTerms: string
  minSpendPence: string
  isActive: boolean
}

type RewardPoolItemValues = {
  id?: string
  rewardName: string
  rewardTerms: string
  minSpendPence: string
  weight: string
  displayOrder: string
  isActive: boolean
}

type LoyaltyCardFormProps = {
  initialValues: LoyaltyCardFormValues
  rewardPoolItems: RewardPoolItemValues[]
  merchantName: string
  locationName: string
}

const initialCardState: LoyaltyCardActionState = {}
const initialPoolState: RewardPoolItemActionState = {}

export function LoyaltyCardForm({
  initialValues,
  rewardPoolItems,
  merchantName,
  locationName,
}: LoyaltyCardFormProps) {
  const [state, action, pending] = useActionState(
    saveLoyaltyCardAction,
    initialCardState
  )
  const [draft, setDraft] = useState(initialValues)

  function updateDraft<K extends keyof LoyaltyCardFormValues>(
    field: K,
    value: LoyaltyCardFormValues[K]
  ) {
    setDraft((currentDraft) => ({ ...currentDraft, [field]: value }))
  }

  const activeRewardCount = rewardPoolItems.filter(
    (item) => item.isActive
  ).length

  return (
    <div className="grid gap-6 lg:grid-cols-[minmax(0,1fr)_320px]">
      <div className="grid gap-6">
        <form action={action} className="surface-card grid gap-5 p-6">
          <input type="hidden" name="cardId" value={draft.cardId ?? ""} />
          <input
            type="hidden"
            name="minSpendPence"
            value={draft.minSpendPence}
          />
          <PageTitle
            eyebrow="Step 1 · Build card"
            title="Build your visit card"
            description={`One active card for ${locationName}, with a reward revealed after the final qualifying visit.`}
            titleClassName="sm:text-3xl"
          />

          <Field
            id="cardName"
            label="Card name"
            name="cardName"
            value={draft.cardName}
            onChange={(event) => updateDraft("cardName", event.target.value)}
            error={state.errors?.cardName}
          />

          <Field
            id="stampsRequired"
            label="Visits to reveal"
            name="stampsRequired"
            inputMode="numeric"
            pattern="[0-9]*"
            value={draft.stampsRequired}
            onChange={(event) =>
              updateDraft("stampsRequired", event.target.value)
            }
            error={state.errors?.stampsRequired}
          />

          <TextareaField
            id="rewardTerms"
            label="Mystery reward terms"
            name="rewardTerms"
            value={draft.rewardTerms}
            onChange={(event) => updateDraft("rewardTerms", event.target.value)}
            error={state.errors?.rewardTerms}
          />

          <label className="flex items-center justify-between gap-4 rounded-lg border-2 border-ink bg-secondary/50 px-4 py-3 text-sm font-bold">
            <span>Card active</span>
            <input
              name="isActive"
              type="checkbox"
              checked={draft.isActive}
              onChange={(event) =>
                updateDraft("isActive", event.target.checked)
              }
              className="size-5 accent-primary"
            />
          </label>

          {state.errors?.form ? (
            <p className="rounded-lg border border-destructive/30 bg-destructive/10 px-3 py-2 text-sm text-destructive">
              {state.errors.form}
            </p>
          ) : null}

          <Button type="submit" disabled={pending} className="w-full">
            {pending ? "Saving..." : draft.cardId ? "Save card" : "Create card"}
          </Button>
        </form>

        <section className="surface-card grid gap-4 p-6">
          <SectionHeader
            eyebrow="Step 2 · Reward"
            title="Add a surprise reward"
            description="At least 3 active rewards are needed before the venue QR can launch or a final stamp can reveal a prize."
          />

          {draft.cardId ? (
            <div className="grid gap-4">
              {activeRewardCount < 3 ? (
                <StatusBanner
                  tone="warning"
                  title="QR launch is blocked until 3 rewards are active."
                >
                  Add {3 - activeRewardCount} more active reward
                  {3 - activeRewardCount === 1 ? "" : "s"} so customers can
                  reveal a prize on their final stamp.
                </StatusBanner>
              ) : (
                <StatusBanner tone="success" title="QR launch eligible.">
                  {activeRewardCount} active reward
                  {activeRewardCount === 1 ? "" : "s"} can be assigned when a
                  customer completes the card.
                </StatusBanner>
              )}
              {rewardPoolItems.length === 0 ? (
                <EmptyState
                  icon={GiftIcon}
                  title="No rewards in the pool yet"
                  description="Create at least 3 active mystery rewards so the QR launch checklist can pass."
                  headingLevel={3}
                />
              ) : null}
              {rewardPoolItems.map((item) => (
                <RewardPoolItemForm
                  key={item.id}
                  loyaltyCardId={draft.cardId ?? ""}
                  initialValues={item}
                />
              ))}
              <RewardPoolItemForm
                loyaltyCardId={draft.cardId}
                initialValues={{
                  rewardName: "",
                  rewardTerms: "",
                  minSpendPence: "",
                  weight: "1",
                  displayOrder: String(rewardPoolItems.length + 1),
                  isActive: true,
                }}
                isNew
              />
            </div>
          ) : (
            <StatusBanner tone="neutral" title="Save the card before rewards.">
              The reward pool is tied to a saved loyalty card id, so this step
              unlocks after the first card save.
            </StatusBanner>
          )}
        </section>
      </div>

      <StampCardPreview
        merchantName={merchantName}
        locationName={locationName}
        draft={draft}
        activeRewardCount={activeRewardCount}
      />
    </div>
  )
}

function RewardPoolItemForm({
  loyaltyCardId,
  initialValues,
  isNew = false,
}: {
  loyaltyCardId: string
  initialValues: RewardPoolItemValues
  isNew?: boolean
}) {
  const [state, action, pending] = useActionState(
    saveRewardPoolItemAction,
    initialPoolState
  )
  const [draft, setDraft] = useState(initialValues)

  function updateDraft<K extends keyof RewardPoolItemValues>(
    field: K,
    value: RewardPoolItemValues[K]
  ) {
    setDraft((currentDraft) => ({ ...currentDraft, [field]: value }))
  }

  const advancedTouched =
    Boolean(state.errors?.weight) ||
    Boolean(state.errors?.displayOrder) ||
    Boolean(state.errors?.minSpendPence) ||
    draft.minSpendPence !== ""

  return (
    <div className="surface-card grid gap-4 p-4">
      {!isNew ? (
        <div className="flex flex-wrap items-start justify-between gap-3 rounded-lg border-2 border-dashed border-ink/15 bg-secondary/50 px-4 py-3">
          <div>
            <p className="text-sm font-extrabold">
              {draft.rewardName || "Untitled reward"}
            </p>
            <p className="mt-1 font-mono text-xs leading-5 text-muted-foreground">
              Minimum spend:{" "}
              {draft.minSpendPence
                ? `£${formatPence(draft.minSpendPence)}`
                : "None"}{" "}
              · Weight: {draft.weight || "1"} · Order:{" "}
              {draft.displayOrder || "0"}
            </p>
          </div>
          <MonoTag tone={draft.isActive ? "leaf" : "plain"}>
            {draft.isActive ? "Active reward" : "Inactive reward"}
          </MonoTag>
        </div>
      ) : null}
      <form action={action} className="grid gap-4">
        <input type="hidden" name="loyaltyCardId" value={loyaltyCardId} />
        <input type="hidden" name="rewardPoolItemId" value={draft.id ?? ""} />
        <Field
          id={`${draft.id ?? "new"}-rewardName`}
          label="Reward name"
          name="rewardName"
          value={draft.rewardName}
          onChange={(event) => updateDraft("rewardName", event.target.value)}
          error={state.errors?.rewardName}
        />
        <TextareaField
          id={`${draft.id ?? "new"}-rewardTerms`}
          label="Reward terms"
          name="rewardTerms"
          rows={3}
          value={draft.rewardTerms}
          onChange={(event) => updateDraft("rewardTerms", event.target.value)}
          error={state.errors?.rewardTerms}
        />
        <label className="flex items-center justify-between gap-3 rounded-lg border-2 border-ink bg-secondary/50 px-4 py-3 text-sm font-bold">
          <span>Active reward</span>
          <input
            name="isActive"
            type="checkbox"
            checked={draft.isActive}
            onChange={(event) => updateDraft("isActive", event.target.checked)}
            className="size-5 accent-primary"
          />
        </label>

        <Disclosure
          label="Weighting, order and spend"
          defaultOpen={advancedTouched}
        >
          <p className="text-xs leading-5 text-muted-foreground">
            Defaults are fine to launch. Weight makes a reward more likely;
            order sorts the list; minimum spend is optional.
          </p>
          <div className="grid gap-3 sm:grid-cols-3">
            <Field
              id={`${draft.id ?? "new"}-weight`}
              label="Weight"
              name="weight"
              inputMode="numeric"
              pattern="[0-9]*"
              value={draft.weight}
              onChange={(event) => updateDraft("weight", event.target.value)}
              error={state.errors?.weight}
            />
            <Field
              id={`${draft.id ?? "new"}-displayOrder`}
              label="Order"
              name="displayOrder"
              inputMode="numeric"
              pattern="[0-9]*"
              value={draft.displayOrder}
              onChange={(event) =>
                updateDraft("displayOrder", event.target.value)
              }
              error={state.errors?.displayOrder}
            />
            <Field
              id={`${draft.id ?? "new"}-minSpendPence`}
              label="Min spend"
              name="minSpendPence"
              inputMode="numeric"
              pattern="[0-9]*"
              placeholder="Optional pence"
              value={draft.minSpendPence}
              onChange={(event) =>
                updateDraft("minSpendPence", event.target.value)
              }
              error={state.errors?.minSpendPence}
            />
          </div>
        </Disclosure>

        {state.errors?.form ? (
          <p className="rounded-lg border border-destructive/30 bg-destructive/10 px-3 py-2 text-sm text-destructive">
            {state.errors.form}
          </p>
        ) : null}
        <div className="flex flex-wrap gap-2">
          <Button type="submit" disabled={pending}>
            {pending ? "Saving..." : isNew ? "Add reward" : "Save reward"}
          </Button>
        </div>
      </form>
      {!isNew && draft.id ? (
        <form action={deleteRewardPoolItemAction}>
          <input type="hidden" name="rewardPoolItemId" value={draft.id} />
          <Button type="submit" variant="outline">
            Delete or archive
          </Button>
